ull,"price_bani":0,"photo_url":"/events/instagram/targ-halloween-2024/DBePBVjI4W6-b62720452b5c.webp"},{"slug":"treasure-hunt-8-around-the-world-2024","title":"Treasure Hunt 8.0","subtitle":"Around the World","about":"Echipe de doi până la cinci participanți au explorat culturi și tradiții prin probe în Parcul Herăstrău. Donațiile au sprijinit o familie nevoiașă din București.","start_date":"2024-09-21","end_date":null,"start_time":"11:00","end_time":null,"venue":"Parcul Herăstrău","address":"Intrarea de lângă Arcul de Triumf, Aleea Michael Jackson, București","price_bani":0,"photo_url":"/events/instagram/treasure-hunt-8-around-the-world-2024/C_n6oD0ohfi-113a86e55884.webp"}]$legacy_events$::jsonb
  ) as source(
    slug text,
    title text,
    subtitle text,
    about text,
    start_date date,
    end_date date,
    start_time time,
    end_time time,
    venue text,
    address text,
    price_bani integer,
    photo_url text
  )
),
legacy_times as (
  select
    source.*,
    (source.start_date + source.start_time) at time zone 'Europe/Bucharest' as starts_at,
    case
      when source.end_date is not null then
        (source.end_date + coalesce(source.end_time, source.start_time)) at time zone 'Europe/Bucharest'
      when source.end_time is not null and source.end_time <= source.start_time then
        ((source.start_date + 1) + source.end_time) at time zone 'Europe/Bucharest'
      when source.end_time is not null then
        (source.start_date + source.end_time) at time zone 'Europe/Bucharest'
      else
        ((source.start_date + source.start_time) at time zone 'Europe/Bucharest') + interval '4 hours'
    end as calculated_ends_at
  from legacy_source source
)
insert into public.events(
  slug,
  title,
  subtitle,
  starts_at,
  ends_at,
  doors,
  date_label,
  date_long,
  venue,
  venue_line,
  price_bani,
  capacity,
  status,
  accent,
  photo_url,
  about,
  program,
  perks
)
select
  legacy.slug,
  legacy.title,
  legacy.subtitle,
  legacy.starts_at,
  greatest(legacy.starts_at + interval '1 minute', legacy.calculated_ends_at),
  to_char(legacy.start_time, 'HH24:MI'),
  legacy.start_date::text,
  legacy.start_date::text,
  legacy.venue,
  legacy.address,
  greatest(legacy.price_bani, 0),
  1,
  'past'::public.event_status,
  '#009FE3',
  legacy.photo_url,
  legacy.about,
  '[]'::jsonb,
  '[]'::jsonb
from legacy_times legacy
on conflict (slug) do nothing;
